//! `cargo xtask progress [--write]` -- keeps the README progress chart in step
//! with `docs/progress.txt`. Without `--write` it fails if the README block is
//! stale; with it, it rewrites the block.

use crate::Gate;
use std::path::Path;

const DATA: &str = "docs/progress.txt";
const README: &str = "README.md";
const BEGIN: &str =
    "<!-- progress:begin (generated by `cargo xtask progress --write`; edit docs/progress.txt) -->";
const END: &str = "<!-- progress:end -->";

/// Parse `phase|percent|name` lines; `#` comments and blanks skipped.
pub fn parse(text: &str) -> Result<Vec<(u32, u32, String)>, String> {
    let mut out = Vec::new();
    for (i, line) in text.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut it = line.splitn(3, '|');
        let (Some(p), Some(pc), Some(name)) = (it.next(), it.next(), it.next()) else {
            return Err(format!("line {}: expected phase|percent|name", i + 1));
        };
        let p: u32 = p
            .trim()
            .parse()
            .map_err(|_| format!("line {}: bad phase", i + 1))?;
        let pc: u32 = pc
            .trim()
            .parse()
            .map_err(|_| format!("line {}: bad percent", i + 1))?;
        if pc > 100 {
            return Err(format!("line {}: percent over 100", i + 1));
        }
        out.push((p, pc, name.trim().to_string()));
    }
    if out.is_empty() {
        return Err("no phases".into());
    }
    Ok(out)
}

/// The generated block, markers included, no trailing newline.
pub fn render(rows: &[(u32, u32, String)]) -> String {
    let mut s = String::new();
    s.push_str(BEGIN);
    s.push_str("\n```text\n");
    for (p, pc, name) in rows {
        let k = ((*pc + 2) / 5) as usize;
        let label = format!("{p:<2} {name}");
        s.push_str(&format!(
            "{label:<27}{}{} {pc:>3}%\n",
            "\u{2588}".repeat(k),
            "\u{2591}".repeat(20 - k)
        ));
    }
    let avg = (rows.iter().map(|r| r.1).sum::<u32>() as f64 / rows.len() as f64).round() as u32;
    s.push_str(&format!("{:<27}{avg}%\n", "OVERALL"));
    s.push_str("```\n");
    s.push_str("Estimates by the maintainers, not measurements; a phase is only closed when its gate passes in CI on Windows and Linux.\n");
    s.push_str(END);
    s
}

/// Replace the marked block in `readme`; `None` if the markers are missing.
pub fn splice(readme: &str, block: &str) -> Option<String> {
    let b = readme.find("<!-- progress:begin")?;
    let e = readme.find(END)? + END.len();
    if e < b {
        return None;
    }
    Some(format!("{}{}{}", &readme[..b], block, &readme[e..]))
}

pub fn run(g: &mut Gate, root: &Path, args: &[String]) {
    let write = args.iter().any(|a| a == "--write");
    let data = match std::fs::read_to_string(root.join(DATA)) {
        Ok(d) => d,
        Err(e) => return g.fail(format!("cannot read {DATA}: {e}")),
    };
    let rows = match parse(&data) {
        Ok(r) => r,
        Err(e) => return g.fail(format!("{DATA}: {e}")),
    };
    let readme = match std::fs::read_to_string(root.join(README)) {
        Ok(r) => r,
        Err(e) => return g.fail(format!("cannot read {README}: {e}")),
    };
    let Some(new) = splice(&readme, &render(&rows)) else {
        return g.fail(format!(
            "{README} has no progress:begin / progress:end markers"
        ));
    };
    if new == readme {
        g.ok("README progress chart is current");
    } else if write {
        match std::fs::write(root.join(README), new) {
            Ok(()) => g.ok("README progress chart rewritten"),
            Err(e) => g.fail(format!("cannot write {README}: {e}")),
        }
    } else {
        g.fail("README progress chart is stale; run `cargo xtask progress --write` and commit");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_and_renders() {
        let rows = parse("# c\n0|95|A\n1|5|B\n").unwrap();
        let r = render(&rows);
        assert!(r.contains("0  A"));
        assert!(r.contains(" 95%"));
        assert!(r.contains("OVERALL                    50%"));
    }

    #[test]
    fn rejects_bad_input() {
        assert!(parse("0|101|A").is_err());
        assert!(parse("x|1|A").is_err());
        assert!(parse("").is_err());
    }

    #[test]
    fn splice_replaces_only_the_block() {
        let rows = parse("0|50|A").unwrap();
        let readme = format!("top\n{BEGIN}\nold\n{END}\nbottom\n");
        let out = splice(&readme, &render(&rows)).unwrap();
        assert!(out.starts_with("top\n") && out.ends_with("\nbottom\n") && !out.contains("old"));
        assert_eq!(splice(&out, &render(&rows)).unwrap(), out);
        assert!(splice("no markers", "x").is_none());
    }
}
